BEGIN READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT coalesce(json_agg(q),'[]'::json) FROM (
 SELECT id,topic_id,created_at,subject,message_id,length(body) AS body_length,left(body,16000) AS body
 FROM messages
 WHERE subject ~* '(^|[^[:alnum:]_])GIN([^[:alnum:]_]|$)'
 AND body ILIKE '%consistent%'
 AND (body ILIKE '%cache%' OR body ILIKE '%memo%' OR body ILIKE '%truth table%')
 ORDER BY created_at DESC,id DESC LIMIT 20
) q;
COMMIT;
